/**
 * Lightweight Semantic DOM & Attribute Assertion Engine.
 * Parses HTML strings generated by SSR and verifies tags, classes, attributes, and text.
 */
import assert from 'node:assert/strict';

function escapeRegex(str) {
  return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/**
 * Parses a simple or compound CSS selector into tag, classes, and attributes.
 * Examples:
 *   - 'nav'
 *   - '.mobile-bottom-nav'
 *   - '[role="tab"]'
 *   - 'nav[aria-label="Breadcrumb"]'
 *   - 'button.tab-btn[role="tab"]'
 *   - 'button[role="tab"][aria-selected="true"]'
 */
export function parseSelector(selector) {
  let s = selector.trim();
  let tag = null;
  const classes = [];
  const attributes = [];

  // Match leading tag if present (or :root)
  if (s.startsWith(':root')) {
    tag = ':root';
    s = s.slice(5);
  } else {
    const tagMatch = s.match(/^([a-zA-Z0-9:-]+)/);
    if (tagMatch) {
      tag = tagMatch[1].toLowerCase();
      s = s.slice(tagMatch[0].length);
    }
  }

  // Parse remaining classes and attributes
  while (s.length > 0) {
    if (s.startsWith('.')) {
      const clsMatch = s.match(/^\.([a-zA-Z0-9_-]+)/);
      if (clsMatch) {
        classes.push(clsMatch[1]);
        s = s.slice(clsMatch[0].length);
        continue;
      }
    }
    if (s.startsWith('[')) {
      const attrMatch = s.match(/^\[([a-zA-Z0-9_:-]+)(?:([~|^$*]?=)(["']?)(.*?)\3)?\]/);
      if (attrMatch) {
        const name = attrMatch[1];
        const op = attrMatch[2] || null;
        const value = attrMatch[4] !== undefined ? attrMatch[4] : null;
        attributes.push({ name, op, value });
        s = s.slice(attrMatch[0].length);
        continue;
      }
    }
    break;
  }

  return { tag, classes, attributes };
}

function tagMatchesParsed(tagName, attrString, parsed) {
  // 1. Tag name check
  if (parsed.tag && parsed.tag !== '*' && parsed.tag !== ':root') {
    if (tagName.toLowerCase() !== parsed.tag) return false;
  }

  // 2. Class check
  if (parsed.classes.length > 0) {
    const classMatch = attrString.match(/(?:^|\s)class=["']([^"']*)["']/i);
    if (!classMatch) return false;
    const elementClasses = classMatch[1].trim().split(/\s+/);
    for (const cls of parsed.classes) {
      if (!elementClasses.includes(cls)) return false;
    }
  }

  // 3. Attribute check
  for (const attr of parsed.attributes) {
    if (attr.value === null) {
      const existsRe = new RegExp(`(?:^|\\s)${escapeRegex(attr.name)}(?:\\s*=|\\s|/?>|$)`, 'i');
      if (!existsRe.test(attrString)) return false;
    } else {
      const escVal = escapeRegex(attr.value);
      if (attr.op === '~=') {
        const re = new RegExp(`(?:^|\\s)${escapeRegex(attr.name)}=["'][^"']*\\b${escVal}\\b[^"']*["']`, 'i');
        if (!re.test(attrString)) return false;
      } else {
        const re = new RegExp(`(?:^|\\s)${escapeRegex(attr.name)}=["']${escVal}["']`, 'i');
        if (!re.test(attrString)) return false;
      }
    }
  }

  return true;
}

export function matchSelector(html, selector) {
  if (!html || !selector) return false;
  const parsed = parseSelector(selector);

  const tagRegex = /<([a-zA-Z0-9:-]+)((?:\s+[^"'>]*(?:"[^"]*"|'[^']*')*)*?)\s*\/?>/g;
  let match;
  while ((match = tagRegex.exec(html)) !== null) {
    if (tagMatchesParsed(match[1], match[2] || '', parsed)) {
      return true;
    }
  }

  if (parsed.tag === ':root' && parsed.attributes.length > 0) {
    for (const attr of parsed.attributes) {
      const re = new RegExp(`${escapeRegex(attr.name)}=["']${escapeRegex(attr.value)}["']`, 'i');
      if (re.test(html)) return true;
    }
  }

  return false;
}

export function countMatches(html, selector) {
  if (!html || !selector) return 0;
  const parsed = parseSelector(selector);
  const tagRegex = /<([a-zA-Z0-9:-]+)((?:\s+[^"'>]*(?:"[^"]*"|'[^']*')*)*?)\s*\/?>/g;
  let count = 0;
  let match;
  while ((match = tagRegex.exec(html)) !== null) {
    if (tagMatchesParsed(match[1], match[2] || '', parsed)) {
      count++;
    }
  }
  return count;
}

export function assertElementExists(html, selector, message) {
  assert.ok(
    matchSelector(html, selector),
    message || `Expected element matching selector "${selector}" in HTML:\n${html}`
  );
}

export function assertElementCount(html, selector, expectedCount, message) {
  const count = countMatches(html, selector);
  assert.equal(
    count,
    expectedCount,
    message || `Expected ${expectedCount} elements matching selector "${selector}", found ${count}.`
  );
}

export function assertAttribute(html, selector, attr, expectedValue, message) {
  const re = new RegExp(`${attr}=["']${expectedValue}["']`);
  assert.ok(
    re.test(html),
    message || `Expected attribute ${attr}="${expectedValue}" in HTML snippet:\n${html}`
  );
}

export function assertTextContent(html, expectedSubstring, message) {
  assert.ok(
    html.includes(expectedSubstring),
    message || `Expected HTML to contain text "${expectedSubstring}".`
  );
}

export function assertClass(html, selector, expectedClass, message) {
  const re = new RegExp(`class=["'][^"']*\\b${expectedClass}\\b[^"']*["']`);
  assert.ok(
    re.test(html),
    message || `Expected class "${expectedClass}" in HTML snippet:\n${html}`
  );
}

export function assertTabSelected(html, tabLabel, isSelected = true) {
  const regex = new RegExp(
    `<button[^>]*aria-selected=["'](${isSelected})["'][^>]*>[\\s\\S]*?${tabLabel}[\\s\\S]*?<\\/button>`,
    'i'
  );
  assert.ok(
    regex.test(html),
    `Expected tab "${tabLabel}" to have aria-selected="${isSelected}".`
  );
}
